class TestCollapsedToolbarMigration(MarionetteTestCase):
    """
    Tests that the legacy collapsed="true"/"false" values, as written by
    Thunderbird 9 to 60, are rewritten to the values the current code persists,
    since the presence of *any* value for that attribute now collapses the
    toolbar.
    """

    # The toolbars are near the end of messengercompose.xhtml, so wait for the
    # compose window to be ready before looking for them.
    get_collapsed_attributes = """
        const [resolve] = arguments;

        function finish() {
            resolve([
                document.getElementById("composeToolbar2").getAttribute("collapsed"),
                document.getElementById("compose-toolbar-menubar2").getAttribute("collapsed"),
            ]);
        }

        if (window.composeEditorReady) {
            finish();
        } else {
            window.addEventListener("compose-editor-ready", finish, { once: true });
        }
    """

    get_xulstore_value = """
        const [url, id] = arguments;
        if (!Services.xulStore.hasValue(url, id, "collapsed")) {
            return null;
        }
        return Services.xulStore.getValue(url, id, "collapsed");
    """

    get_pref_value = """
        return Services.prefs.getIntPref("mail.ui-rdf.version", -1);
    """
